+          manager,
+          todoId,
+        ).messages.any((m) => m.content.contains('for todo')),
+        isTrue,
+      );
+      expect(await bindingText(env, 'notes'), contains(notesId));
+      expect(await bindingText(env, 'todo'), contains(todoId));
