        context: context,
        isScrollControlled: true,
        builder: (context) => _FaMessageSheet(app: widget.app),
      );
      if (message == null || message.trim().isEmpty || !mounted) return;
      await _sendFaMessage(message);
    } finally {
      if (mounted) setState(() => _faSheetOpen = false);
    }
  }

