class AppPermissionsDialogState extends State<AppPermissionsDialog> {
  late AppPermissions _current;
  bool _changed = false;

  @override
  void initState() {
    super.initState();
    _current = widget.store.forApp(widget.app).effective();
  }

  void _set(AppPermissions next) {
    setState(() {
      _current = next;
      _changed = true;
    });
