          const SizedBox(height: 12),
          FilledButton.icon(
            icon: const Icon(Icons.send),
            label: Text(context.l10n.appsSendToFa),
            onPressed: () => Navigator.of(context).pop(_controller.text),
          ),
        ],
      ),
    );
  }
}

